function bounds(f) {
  const xs = f.outline.flatMap((e) => [e.from[0], e.to[0]]);
  const ys = f.outline.flatMap((e) => [e.from[1], e.to[1]]);
  return [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
}
